import{_ as d,o,c as t,a5 as c}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"变量与常量的声明","description":"","frontmatter":{"title":"变量与常量的声明","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Java基础","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第一部分：语言基础/01-基础语法/一、变量和数据类型/变量与常量的声明.md","filePath":"posts/java快速入门/第一部分：语言基础/01-基础语法/一、变量和数据类型/变量与常量的声明.md"}'),a={name:"posts/java快速入门/第一部分：语言基础/01-基础语法/一、变量和数据类型/变量与常量的声明.md"};function n(p,e,r,s,_,l){return o(),t("div",null,[...e[0]||(e[0]=[c('<div><p>变量是具备名称的一块内存空间，用来存储可变动的数据内容。当程序需要存取某个内存在的内容时，就可以通过变量名称将数据从内存中取出或写入这个内存空间。在使用变量前，必须对变量进行声明，<code>Java</code>语言的变量声明语句可分为“数据类型”与“变量名称”两部分。声明语句语法如下： 数据类型 变量名称；<code>//</code> 符号“；”表示语句的结束，如：</p><p>int num1=30; int num2=77; 这时<code>Java</code>会自动分配<code>4</code>字节的内存空间给变量<code>num1</code>和<code>num2</code>，它们的存储值分别为<code>30</code>和<code>77</code>。当程序运行过程中需要存取这块内存空间的内容时，就可以直接使用变量名称<code>num1</code>和</p><p><code>num2</code></p><p>进行存取，如图：</p><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td>内存位置</td><td>值</td><td>变量名称</td></tr><tr><td><code>1024</code></td><td><code>30</code></td><td><code>num1</code></td></tr><tr><td><code>1028</code></td><td><code>77</code></td><td><code>num2</code></td></tr></tbody></table><p>当财时要声明多个相同数据类型的变量时，可以使用逗号“，”来分隔变量名称，例如： <code>long apple,banana;</code> 完成变量的声明后，有些变量可根据需要赋初始值，就是在变量声明的语句中加入初值的设置，语法如下： <strong>数据类型</strong> <strong>变量名称</strong> <code>=</code> <strong>初值；</strong> 例如：</p><p>int apple = 5; boolean a = true,b = false;// 同时声明多个<code>boolean</code>类型的变量并赋初值 在赋初值时，注意数据类型为字符和浮点数的赋值。给<code>char</code>数据类型赋初值有三种方法：字符、<code>Unicode</code>码以及<code>ASCII</code>码，其中初值为字符、<code>Unicode</code>码格式时，必须在字符的左右两边各加上单引号“<code>&#39;</code>”，如：</p><p>char apple = &#39;@&#39;; char apple = &#39;\\u0040&#39;; char apple = 64;// 用‘<code>@</code>’字符对应的<code>ASCII</code>码<code>64</code>来赋初值，<code>ASCII</code>码用十进制数来表示</p></div>',1)])])}const u=d(a,[["render",n]]);export{m as __pageData,u as default};
